#!/usr/bin/env python3
import base64
import io
from pathlib import Path
import tarfile

ROOT = Path(__file__).resolve().parents[1]
ARCHIVE = "[... ELLIPSIZATION ...]"

data = base64.b64decode(ARCHIVE, validate=True)
with tarfile.open(fileobj=io.BytesIO(data), mode="r:gz") as tar:
    members = tar.getmembers()
    for member in members:
        target = (ROOT / member.name).resolve()
        if not target.is_relative_to(ROOT.resolve()):
            raise SystemExit(f"unsafe archive path: {member.name}")
        if member.issym() or member.islnk():
            raise SystemExit(f"archive links are not allowed: {member.name}")
    tar.extractall(ROOT, members=members)

for transient in [
    ROOT / "scripts" / "apply_ollama_overlay.py",
    ROOT / ".github" / "workflows" / "apply-ollama-overlay.yml",
]:
    if transient.exists():
        transient.unlink()
